      valid ? Plot.text([{}], {x: betaMean, y: yMax, text: () =&gt; `M = ${betaMean.toFixed(2)}`, textAnchor: "start", dx: 5, lineAnchor: "top", dy: 2, fontWeight: 600}) : null,
      valid ? Plot.link([{}], {x1: betaMean - betaSd, x2: betaMean + betaSd, y1: barY, y2: barY, stroke: "currentColor", strokeWidth: 1.5, clip: true}) : null,
      valid ? Plot.text([{}], {x: betaMean, y: barY, text: () =&gt; `SD = ${betaSd.toFixed(2)}`, textAnchor: "start", dx: 5, dy: -8, fontWeight: 600}) : null,
