    ]
  })
  const fmt = (x, digits = 2) =&gt; Number.isFinite(x) ? x.toFixed(digits).replace("-", "−") : "—"
  const readout = html`&lt;table class="bd-readout"&gt;
    &lt;tr&gt;&lt;td&gt;Shape&lt;/td&gt;&lt;td&gt;&lt;i&gt;α&lt;/i&gt; = ${valid ? fmt(alpha) : "—"}, &lt;i&gt;β&lt;/i&gt; = ${valid ? fmt(beta) : "—"}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Mean–precision&lt;/td&gt;&lt;td&gt;&lt;i&gt;μ&lt;/i&gt; = ${fmt(mu)}, &lt;i&gt;φ&lt;/i&gt; = ${valid ? fmt(phi) : "—"}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Regression intercepts&lt;/td&gt;&lt;td&gt;logit(&lt;i&gt;μ&lt;/i&gt;) = ${fmt(Math.log(mu / (1 - mu)))}, log(&lt;i&gt;φ&lt;/i&gt;) = ${valid ? fmt(Math.log(phi)) : "—"}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Descriptive&lt;/td&gt;&lt;td&gt;&lt;i&gt;M&lt;/i&gt; = ${fmt(betaMean)}, &lt;i&gt;SD&lt;/i&gt; = ${fmt(betaSd)}, skewness = ${valid ? fmt(skew) : "—"}&lt;/td&gt;&lt;/tr&gt;
  &lt;/table&gt;`

  // right: the space of means and SDs on the scale. the bhatia-davis bound, sqrt((mean - min) * (max - mean)), is the
