    : "Scores pile up against both ends of the scale."
  const [kind, message] = valid
    ? [shape === "hump" ? "ok" : "warn", `&lt;strong&gt;Possible.&lt;/strong&gt; With a mean of ${betaMean.toFixed(2)} on a ${lo} to ${hi} scale, the SD can be at most ${maxSd.toFixed(2)}. ${shapeText}`]
    : ["bad", `&lt;strong&gt;Not possible.&lt;/strong&gt; With a mean of ${betaMean.toFixed(2)} on a ${lo} to ${hi} scale, no data of any kind can have an SD above ${maxSd.toFixed(2)}, and an SD equal to it requires every score to be exactly ${lo} or exactly ${hi}.`]
  const feedback = html`&lt;div class="sb-feedback sb-feedback-${kind}"&gt;`
  feedback.innerHTML = message
  // clicking anywhere in the right plot moves the sliders to that mean and SD, which redraws both plots. a point
  // above the bhatia-davis bound can be chosen, so that the plots show why it is impossible
  clickToSet(right, {width: panelWidth, height: panelHeight, marginLeft: 50, marginRight: 20, marginTop: 24, marginBottom: 45, xDomain: [lo, hi], yDomain: [0, ySpan]}, (m, s) =&gt; {
    setInput(viewof betaMean, snapToInput(viewof betaMean, m))
