{
  if (!smdBounds) return boundsMessage()
  const [lo, hi] = smdBounds, range = hi - lo
  const panelWidth = width &gt;= 640 ? Math.floor((width - 24) / 2) : width
  const panelHeight = 320
  const orange = "#d9622b", blue = "#2780e3", red = "#c0392b"
