  // each condition's SD follows from its mean and the shared precision, as in the plot above
  const sdFor = (m, phi) =&gt; { const u = (m - lo) / range; return range * Math.sqrt(u * (1 - u) / (1 + phi)) }
  const condition = (name, colour, mean) =&gt; {
    const mu = (mean - lo) / range, valid = mu &gt; 0 && mu &lt; 1
    const alpha = mu * phi, beta = (1 - mu) * phi
    return {name, colour, mean, mu, valid, alpha, beta, sd: valid ? sdFor(mean, phi) : NaN}
  }
  const control = condition("Control", orange, smdMean)
  // in SMD mode, find the mean difference that gives the chosen SMD. the SMD grows steadily as the intervention mean
  // moves away from the control mean, and is largest when the intervention mean reaches the end of the scale, where
  // its SD is zero and the pooled SD is the control SD / sqrt(2). an SMD beyond that cannot be reached, whatever the
  // mean difference
  const target = smdUseSmd ? smdInput : null
  const smdOf = x =&gt; { const sdI = sdFor(smdMean + x, phi); return x / Math.sqrt((control.sd ** 2 + sdI ** 2) / 2) }
  const edge = target === null || target &gt;= 0 ? hi - smdMean : lo - smdMean
  const maxSmd = Math.abs(edge) / (control.sd / Math.SQRT2)
  const reachable = target === null || Math.abs(target) &lt; maxSmd
  let smdDiff = smdUseSmd ? 0 : smdInput
  if (target !== null && target !== 0 && reachable) {
    let a = 0, b = 1
    for (let i = 0; i &lt; 60; i++) { const t = (a + b) / 2; if (Math.abs(smdOf(t * edge)) &lt; Math.abs(target)) a = t; else b = t }
    smdDiff = (a + b) / 2 * edge
