function gaChecked(rows) {
  // reads the values in each row of the grid. rows without a label, mean, SD, or sample size are left out. the values
  // are kept as typed, because the number of decimals is part of the input to the tests. a row is only sent to R if its
  // values are numbers that the tests can use
  const plain = /^[+-]?(\d+\.?\d*|\.\d+)$/
  // a minus sign copied from a PDF is often not the ASCII hyphen-minus
  const clean = s =&gt; s.replace(/[−–]/g, "-")
  return rows.map((r, i) =&gt; ({...r, x: clean(r.x), sd: clean(r.sd), row: i + 1}))
    .filter(r =&gt; [r.label, r.x, r.sd, r.n].some(v =&gt; v !== ""))
    .map(r =&gt; {
      const x = Number(r.x), sd = Number(r.sd), n = Number(r.n), items = Number(r.items)
      const problem = r.type === "any" ? "Not whole-number data"
        : r.x === "" ? "No mean given"
        : /,/.test(r.x + r.sd + r.n) ? "Use a decimal point, without thousands separators"
        : !plain.test(r.x) ? "The mean is not a number"
        : r.sd !== "" && !plain.test(r.sd) ? "The SD is not a number"
        : r.sd !== "" && sd &lt; 0 ? "The SD cannot be negative"
        : !/^\d+$/.test(r.n) || n &lt; 2 ? "The sample size must be a whole number of at least 2"
        : !/^\d+$/.test(r.items) || items &lt; 1 ? "Items averaged over must be a whole number of at least 1"
        : r.type === "percent" && (x &lt; 0 || x &gt; 100) ? "A percentage must be between 0 and 100"
        : r.type === "percent" && items !== 1 ? "A percentage is of single yes/no items, so items averaged over must be 1"
        : null
      const notRun = r.type === "any" || r.x === ""
      return {...r, n, items, percent: r.type === "percent", valid: problem === null, problem, notRun}
    })
}

async function gaRun(rows, rounding, roundingName) {
  const {webR, rVersion, version} = await gaSession.get()
  const valid = rows.filter(r =&gt; r.valid)
  let audit = null
  if (valid.length &gt; 0) {
