      // their decimals are kept. scrutiny 1.0.0 takes numbers and the number of decimals instead, so both are supported
      const res = await shelter.evalR(`
        new_api &lt;- "digits_x" %in% names(formals(grim_map))
        dp &lt;- function(s) if (grepl(".", s, fixed = TRUE)) nchar(sub("^[^.]*[.]", "", s)) else 0L
        one &lt;- function(i) {
          xi &lt;- x[i]; sdi &lt;- sd[i]; ni &lt;- n[i]; ki &lt;- items[i]; pc &lt;- percent[i]
          g &lt;- suppressMessages(suppressWarnings(if (new_api)
            grim_map(tibble(x = as.numeric(xi), n = ni), digits_x = dp(xi), items = ki, percent = pc, rounding = rounding) else
            grim_map(tibble(x = xi, n = ni), items = ki, percent = pc, rounding = rounding)))
          out &lt;- data.frame(grim = g$consistency, probability = g$probability, grimmer = NA, reason = "")
          if (nzchar(sdi) && !pc) {
            m &lt;- suppressMessages(suppressWarnings(if (new_api)
              grimmer_map(tibble(x = as.numeric(xi), sd = as.numeric(sdi), n = ni), digits_x = dp(xi), digits_sd = dp(sdi), items = ki, rounding = rounding, show_reason = TRUE) else
              grimmer_map(tibble(x = xi, sd = sdi, n = ni), items = ki, rounding = rounding, show_reason = TRUE)))
            out$grimmer &lt;- m$consistency
            out$reason &lt;- m$reason
          }
          list(out = out, grim = g)
        }
        res &lt;- lapply(seq_along(x), one)
        # audit() summarises all the GRIM results together. the rows were run one at a time, because each can have its
        # own number of items and type, so their grim_map() results are first combined into one
        assign(".ga_audit", as.data.frame(audit(dplyr::bind_rows(lapply(res, function(r) r$grim)))), envir = globalenv())
        do.call(rbind, lapply(res, function(r) r$out))
      `, {env: {x: valid.map(r =&gt; r.x), sd: valid.map(r =&gt; r.sd), n: valid.map(r =&gt; r.n), items: valid.map(r =&gt; r.items), percent: valid.map(r =&gt; r.percent), rounding}})
      const out = await res.toD3()
      valid.forEach((r, i) =&gt; Object.assign(r, out[i]))
      audit = (await (await shelter.evalR(".ga_audit")).toD3())[0]
      await webR.evalRVoid("rm(.ga_audit, envir = globalenv())")
    } finally {
      shelter.purge()
    }
  }
  rows.forEach(r =&gt; Object.assign(r, gaVerdicts(r)))
  return {rows, audit, rounding, roundingName, runAt: new Date(), scrutinyVersion: version, rVersion}
}

function gaVerdicts(r) {
  // the result of each test as text, and the verdict for the row, from scrutiny's output
  // rows of the wrong type or without a mean are not run. rows with values the tests cannot use say why instead
  if (!r.valid) return r.notRun ? {grimResult: "Not run", grimmerResult: "Not run", verdict: "Not tested", kind: "na"}
    : {grimResult: "", grimmerResult: "", verdict: "Not tested", kind: "na"}
  // probability is the share of values that would fail GRIM at this sample size. when it is 0, the test cannot fail, and a
  // pass says nothing
  const uninformative = r.grim && r.probability === 0
  const grimResult = uninformative ? "Uninformative" : r.grim ? "Consistent" : "Inconsistent"
  const grimmerResult = r.sd === "" ? "Not run"
    : r.percent ? "Does not apply to percentages"
    : !r.grim ? "Not run: inconsistent mean"
    : r.grimmer ? "Consistent"
    : "Inconsistent"
  const fails = !r.grim || r.grimmer === false
  // a row is only uninformative if GRIM could not fail and GRIMMER was not run
  const verdict = fails ? "Inconsistent" : uninformative && r.grimmer !== true ? "Uninformative" : "Consistent"
  return {grimResult, grimmerResult, verdict, kind: {Inconsistent: "bad", Uninformative: "na", Consistent: "ok"}[verdict]}
}

function gaResults(run) {
  const {rows, roundingName, scrutinyVersion, rVersion} = run
  const typeName = {whole: "Whole numbers", percent: "%", any: "Not whole numbers, or unsure"}
  // the cells are built one by one, because a fragment of several cells is not kept as separate cells by html``
  const td = (content, colspan = 1) =&gt; { const cell = html`&lt;td&gt;${content}&lt;/td&gt;`; if (colspan &gt; 1) cell.colSpan = colspan; return cell }
  const body = rows.map(r =&gt; {
    const tr = html`&lt;tr class="${r.valid ? "" : "ga-row-none"}"&gt;&lt;/tr&gt;`
    const results = r.valid || r.notRun ? [td(r.grimResult), td(r.grimmerResult)] : [td(r.problem, 2)]
    tr.append(td(r.label || `Row ${r.row}`), td(typeName[r.type]), td(r.x), td(r.sd), td(Number.isFinite(r.n) ? r.n : ""), td(r.items),
