    return tr
  })
  const counts = d3.rollup(rows, v =&gt; v.length, r =&gt; r.verdict)
  const summary = ["Consistent", "Inconsistent", "Uninformative", "Not tested"].map(k =&gt; `${counts.get(k) ?? 0} ${k.toLowerCase()}`).join(", ")
  const cannotFail = rows.filter(r =&gt; r.valid && r.grimResult === "Uninformative").length
  return html`&lt;div&gt;
