}

function gaAuditTable(a) {
  // the summary of all the GRIM results from scrutiny's audit(): testable_cases, incons_rate, mean_grim_prob, and
  // incons_to_prob
  const pct = v =&gt; Number.isFinite(v) ? `${(100 * v).toFixed(1)}%` : "–"
  const rows = [
    ["GRIM-testable means", `${a.testable_cases} of ${a.all_cases}`],
    ["Empirical inconsistency rate", `${pct(a.incons_rate)} (${a.incons_cases} of ${a.all_cases})`],
    ["Expected inconsistency rate", pct(a.mean_grim_prob)],
    ["Ratio of empirical to expected rate", Number.isFinite(a.incons_to_prob) ? a.incons_to_prob.toFixed(2) : "–"]
  ]
  return html`&lt;div&gt;
    &lt;div class="table-responsive"&gt;&lt;table class="table table-sm ga-audit"&gt;
      &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Summary of all GRIM tests&lt;/th&gt;&lt;th&gt;Value&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
