function gaDownloadButton(run) {
  // a button that saves the inputs, scrutiny's output, and the versions used as a CSV file, one row per row of the grid
  // that was not empty, named after the local date and time of the run, e.g. grim_grimmer_results_2026-10-27_14-05-09.csv
  const {rows, rounding, runAt, scrutinyVersion, rVersion} = run
  const columns = ["row", "label", "type", "x", "sd", "n", "items", "grim", "grim_fail_probability", "grim_result", "grimmer", "grimmer_result", "verdict", "problem",
    "rounding", "scrutiny_version", "r_version", "webr_version", "run_at"]
  const records = rows.map(r =&gt; ({...r, grim: r.valid ? r.grim : "", grim_fail_probability: r.valid ? r.probability : "", grim_result: r.grimResult,
    grimmer: r.valid && r.grimmer !== null ? r.grimmer : "", grimmer_result: r.grimmerResult, problem: r.problem ?? "",
    n: Number.isFinite(r.n) ? r.n : "", rounding, scrutiny_version: scrutinyVersion, r_version: rVersion, webr_version: gaWebrVersion, run_at: runAt.toISOString()}))
  const cell = x =&gt; {
    if (x === null || x === undefined) return ""
    const text = typeof x === "boolean" ? (x ? "TRUE" : "FALSE") : String(x)
    // a leading = + - or @ would be read as a formula by spreadsheet programs
    const safe = /^[=+@]/.test(text) ? `'${text}` : text
    return /[",\n\r]/.test(safe) ? `"${safe.replace(/"/g, '""')}"` : safe
  }
  const csv = [columns.join(","), ...records.map(r =&gt; columns.map(c =&gt; cell(r[c])).join(","))].join("\r\n")
  const pad = n =&gt; String(n).padStart(2, "0")
  const d = runAt
  const name = `grim_grimmer_results_${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}_${pad(d.getHours())}-${pad(d.getMinutes())}-${pad(d.getSeconds())}.csv`
  const button = html`&lt;button class="btn btn-quarto"&gt;Download results as CSV&lt;/button&gt;`
  button.onclick = () =&gt; {
    // the byte order mark lets spreadsheet programs read symbols such as – correctly
    const url = URL.createObjectURL(new Blob(["﻿" + csv], {type: "text/csv;charset=utf-8"}))
    const link = html`&lt;a href="${url}" download="${name}"&gt;&lt;/a&gt;`
    document.body.append(link)
    link.click()
    link.remove()
    setTimeout(() =&gt; URL.revokeObjectURL(url), 1000)
  }
  return button
}

