  if (reversed.length) parts.push(`The lower bound is above the upper bound in ${named(reversed)}. These intervals were checked with their bounds in the correct order.`)
  if (!outside.length && !off.length) parts.push(`&lt;strong&gt;All ${valid.length} ${valid.length === 1 ? "estimate is" : "estimates are"} in the middle of ${valid.length === 1 ? "its interval" : "their intervals"}&lt;/strong&gt;, given rounding${log ? " on the log scale" : ""}.`)
  const feedback = html`&lt;div class="sb-feedback sb-feedback-${outside.length ? "bad" : off.length || reversed.length ? "warn" : "ok"}"&gt;`
  feedback.innerHTML = parts.join(" ")
  return html`${plot}${legend}${feedback}${problemNote}`
}







