  const res = await lookupDoi(d);

  if (res.status === "error") {
    yield html`&lt;div class="doi-result error"&gt;
      &lt;span class="badge text-bg-secondary status"&gt;&lt;i class="bi bi-exclamation-triangle-fill"&gt;&lt;/i&gt; Could not check&lt;/span&gt;
      &lt;div class="citation"&gt;${res.message}&lt;/div&gt;
      &lt;div class="doi-text"&gt;${d}&lt;/div&gt;
      ${makeLinks(null)}
    &lt;/div&gt;`;
    return;
  }

  const badges = {
    retracted: html`&lt;span class="badge text-bg-danger status"&gt;&lt;i class="bi bi-x-octagon-fill"&gt;&lt;/i&gt; Retracted&lt;/span&gt;`,
    concern: html`&lt;span class="badge text-bg-warning status"&gt;&lt;i class="bi bi-exclamation-triangle-fill"&gt;&lt;/i&gt; Expression of concern&lt;/span&gt;`,
    other: html`&lt;span class="badge text-bg-info status"&gt;&lt;i class="bi bi-info-circle-fill"&gt;&lt;/i&gt; Other notices (e.g., corrections)&lt;/span&gt;`,
    clean: html`&lt;span class="badge text-bg-success status"&gt;&lt;i class="bi bi-check-circle-fill"&gt;&lt;/i&gt; No notices found&lt;/span&gt;`
  };
  const icons = {retraction: "bi-x-octagon", concern: "bi-exclamation-triangle", correction: "bi-pencil-square", other: "bi-file-earmark-text"};
  const noticeItem = n =&gt; html`&lt;li&gt;
    &lt;i class="bi ${icons[n.type]}"&gt;&lt;/i&gt;
    &lt;strong&gt;${n.label}&lt;/strong&gt;
    &lt;span class="meta"&gt; · ${n.date ?? n.citation ?? ""}${n.date || n.citation ? " · " : ""}source: ${n.source}&lt;/span&gt;
    ${n.url ? html` · &lt;a href="${n.url}" target="_blank" rel="noopener"&gt;view notice&lt;/a&gt;` : ""}
  &lt;/li&gt;`;

  // Which sources could be checked
  const status = (name, s, found) =&gt; s.status === "ok" ? html`&lt;span&gt;&lt;i class="bi bi-check2"&gt;&lt;/i&gt; ${name}${found ?? ""}&lt;/span&gt;`
    : s.status === "notfound" ? html`&lt;span&gt;&lt;i class="bi bi-dash"&gt;&lt;/i&gt; ${name}: not indexed&lt;/span&gt;`
    : html`&lt;span class="unavailable"&gt;&lt;i class="bi bi-exclamation-triangle"&gt;&lt;/i&gt; ${name}: could not be checked&lt;/span&gt;`;
  const checked = html`&lt;div class="checked"&gt;Checked:
    ${status("Crossref and Retraction Watch", res.crossref)}
    ${status("PubMed", res.pubmed, res.pubmed.pmid ? ` (PMID ${res.pubmed.pmid})` : "")}
    &lt;span&gt;&lt;i class="bi bi-check2"&gt;&lt;/i&gt; article title&lt;/span&gt;
  &lt;/div&gt;`;

  yield html`&lt;div class="doi-result ${res.kind}"&gt;
    ${badges[res.kind]}
    &lt;div class="citation"&gt;
      &lt;span class="who"&gt;${res.authors} (${res.year})&lt;/span&gt;
      ${/[.?!]$/.test(res.title) ? res.title : res.title + "."}
      ${res.journal ? html`&lt;em&gt;${res.journal}&lt;/em&gt;.` : ""}
      &lt;a href="${doiUrl(d)}" target="_blank" rel="noopener"&gt;https://doi.org/${d}&lt;/a&gt;
    &lt;/div&gt;
    ${res.notices.length ? html`&lt;ul class="notices"&gt;${res.notices.map(noticeItem)}&lt;/ul&gt;` : ""}
    ${res.isNotice ? html`&lt;div class="note"&gt;This DOI is itself a notice that updates another article.&lt;/div&gt;` : ""}
    ${checked}
    ${res.kind === "retracted" ? "" : html`&lt;div class="coverage"&gt;&lt;i class="bi bi-info-circle"&gt;&lt;/i&gt;
      &lt;span&gt;Crossref, Retraction Watch, and PubMed do not have complete coverage. Even if no retraction or other notice is listed here, check the publisher's page for notices, and PubPeer for comments, using the links below.&lt;/span&gt;&lt;/div&gt;`}
    ${makeLinks(res.pubmed.pmid)}
  &lt;/div&gt;`;
}
